<?php
require_once 'includes/config.php'; require_admin();
$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_config'])) {
 try {
  verify_csrf();
  $year=trim((string)($_POST['academic_year']??'')); $term=trim((string)($_POST['term']??''));
  $name=trim((string)($_POST['fee_name']??'Tuition Fee')); $amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);
  $global=isset($_POST['apply_all']); $classId=(int)($_POST['class_id']??0);
  if($year===''||strlen($year)>20||$term===''||strlen($term)>30||$name===''||strlen($name)>120||$amount===false||$amount<0||(!$global&&$classId<1)) throw new RuntimeException('Provide a valid year, term, fee name, amount and class (unless applying globally).');
  $dbh->beginTransaction();
  if($global) $targets=$dbh->query('SELECT id FROM tblclasses ORDER BY id')->fetchAll(PDO::FETCH_COLUMN); else $targets=[$classId];
  if(!$targets) throw new RuntimeException('No classes exist to receive this fee configuration.');
  $up=$dbh->prepare('INSERT INTO class_fee_configurations(class_id,academic_year,term,fee_name,amount,is_global,active,created_by) VALUES(:c,:y,:t,:n,:a,:g,1,:u) ON DUPLICATE KEY UPDATE amount=VALUES(amount),is_global=VALUES(is_global),active=1,updated_at=NOW()');
  $sumq=$dbh->prepare('SELECT COALESCE(SUM(amount),0) FROM class_fee_configurations WHERE class_id=:c AND academic_year=:y AND term=:t AND active=1');
  $ob=$dbh->prepare('INSERT INTO student_term_fees(student_id,class_id,academic_year,term,amount_due,notes,created_by) SELECT StudentId,ClassId,:y,:t,:a,:n,:u FROM tblstudents WHERE ClassId=:c ON DUPLICATE KEY UPDATE class_id=VALUES(class_id),amount_due=VALUES(amount_due),notes=VALUES(notes),updated_at=NOW()');
  foreach($targets as $cid){$up->execute([':c'=>(int)$cid,':y'=>$year,':t'=>$term,':n'=>$name,':a'=>$amount,':g'=>$global?1:0,':u'=>(int)($_SESSION['admin_id']??0)]);
   // Only set obligations from this package if the student has no recorded payments; never overwrite paid ledgers.
   $safe=$dbh->prepare('SELECT COUNT(*) FROM student_term_fees f JOIN student_fee_payments p ON p.fee_id=f.id WHERE f.class_id=:c AND f.academic_year=:y AND f.term=:t');$safe->execute([':c'=>(int)$cid,':y'=>$year,':t'=>$term]);
   if((int)$safe->fetchColumn()===0){$sumq->execute([':c'=>(int)$cid,':y'=>$year,':t'=>$term]);$total=(float)$sumq->fetchColumn();$ob->execute([':y'=>$year,':t'=>$term,':a'=>$total,':n'=>'Applied configured fee packages',':u'=>(int)($_SESSION['admin_id']??0),':c'=>(int)$cid]);}
  }
  $dbh->commit(); audit_log($dbh,'FEE_CONFIG_SAVED',($global?'Global':'Class-specific').' fee configuration '.$name.' '.$year.' '.$term.' amount '.$amount);$msg='Fee configuration applied to '.count($targets).' class(es). Existing ledgers with payments were not overwritten.';
 }catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not save fee configuration. Confirm Phase 11 migration is installed.';error_log('SRMS fee config: '.$e->getMessage());}
}
$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassName,Section')->fetchAll();
$rows=[];try{$rows=$dbh->query('SELECT f.*,c.ClassName,c.Section FROM class_fee_configurations f JOIN tblclasses c ON c.id=f.class_id ORDER BY f.academic_year DESC,f.term,c.ClassName')->fetchAll();}catch(Throwable $e){}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fee Configurations | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container srms-page"><p><a href="manage-fees.php">← Fees Management</a></p><h2>Universal Fee Configuration</h2><p>Configure fees for one class or roll the package out to every class. Ledgers that already have payments are protected from being overwritten.</p><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel panel-default"><div class="panel-heading">Create / update fee package</div><div class="panel-body"><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="save_config" value="1"><div class="col-md-3 form-group"><label>Fee name</label><input name="fee_name" class="form-control" maxlength="120" value="Tuition Fee" required></div><div class="col-md-2 form-group"><label>Academic year</label><input name="academic_year" class="form-control" placeholder="2026/2027" maxlength="20" required></div><div class="col-md-2 form-group"><label>Term</label><select name="term" class="form-control"><option>Term 1</option><option>Term 2</option><option>Term 3</option><option>Final</option></select></div><div class="col-md-2 form-group"><label>Amount (MWK)</label><input type="number" name="amount" min="0" step="0.01" class="form-control" required></div><div class="col-md-3 form-group"><label>Class (if not global)</label><select name="class_id" class="form-control"><option value="0">Choose class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-md-12 form-group"><label><input type="checkbox" name="apply_all" value="1"> Apply to All Classes</label><p class="help-block">Applies this configuration to every class in the system.</p></div><div class="col-md-12"><button class="btn btn-primary">Save and apply package</button></div></form></div></div><div class="panel panel-default"><div class="panel-heading">Configured fee packages</div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Fee</th><th>Class</th><th>Year</th><th>Term</th><th>Amount (MWK)</th><th>Rollout</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fee_name'])?></td><td><?=e($r['ClassName'].' '.$r['Section'])?></td><td><?=e($r['academic_year'])?></td><td><?=e($r['term'])?></td><td>MWK <?=number_format((float)$r['amount'],2)?></td><td><?=$r['is_global']?'Global':'Class'?></td><td><?=$r['active']?'Active':'Inactive'?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No configurations yet, or Phase 11 migration is not installed.</td></tr><?php endif;?></tbody></table></div></div></div></main></div></div></div></div></body></html>
